import { Page, Locator } from '@playwright/test';

// Single Responsibility: encapsulates interactions with the login page only
export class LoginPage {
  private readonly page: Page;
  private readonly usernameField: Locator;
  private readonly passwordField: Locator;
  private readonly loginButton: Locator;
  private readonly errorContainer: Locator;

  constructor(page: Page) {
    this.page = page;
    this.usernameField = page.locator('#user-name');
    this.passwordField = page.locator('#password');
    this.loginButton = page.locator('#login-button');
    this.errorContainer = page.locator('[data-test="error"]');
  }

  // Navigate to the login page (baseURL is set in playwright.config.ts)
  async goto(): Promise<void> {
    await this.page.goto('/');
  }

  // Perform login with given credentials
  async login(username: string, password: string): Promise<void> {
    await this.usernameField.fill(username);
    await this.passwordField.fill(password);
    await this.loginButton.click();
  }

  // Get the visible error text (if any)
  async getErrorText(): Promise<string> {
    if (await this.errorContainer.isVisible()) {
      return (await this.errorContainer.textContent())?.trim() ?? '';
    }
    return '';
  }

  // Expose error locator for assertions if needed
  get error() {
    return this.errorContainer;
  }
}

import { Page, Locator } from '@playwright/test';

// Represents the products (inventory) page after successful login
export class ProductsPage {
  private readonly page: Page;
  private readonly inventoryContainer: Locator;
  private readonly pageTitle: Locator;

  constructor(page: Page) {
    this.page = page;
    this.inventoryContainer = page.locator('#inventory_container');
    this.pageTitle = page.locator('.title');
  }

  async isOpen(): Promise<boolean> {
    return this.inventoryContainer.isVisible();
  }

  async getTitle(): Promise<string> {
    return (await this.pageTitle.textContent())?.trim() ?? '';
  }
}

import { test, expect } from '@playwright/test';
import { LoginPage } from '../src/pages/LoginPage';
import { ProductsPage } from '../src/pages/ProductsPage';

test.describe('SauceDemo negative login tests', () => {
  test('shows error for invalid credentials', async ({ page }) => {
    const login = new LoginPage(page);
    const products = new ProductsPage(page);

    await login.goto();

    // Attempt with invalid username and password
    await login.login('invalid_user', 'wrong_password');

    // Expect to stay on login page and show proper error message
    const errorText = await login.getErrorText();
    expect(errorText).toContain('Username and password do not match any user');

    // Ensure we did not navigate to products page
    expect(await products.isOpen()).toBeFalsy();
  });

  test('locked out user cannot login and sees locked out message', async ({ page }) => {
    const login = new LoginPage(page);
    const products = new ProductsPage(page);

    await login.goto();

    // locked_out_user is a known account on saucedemo
    await login.login('locked_out_user', 'secret_sauce');

    const errorText = await login.getErrorText();
    expect(errorText).toContain('Sorry, this user has been locked out.');

    // Verify products page is not accessible
    expect(await products.isOpen()).toBeFalsy();
  });
});

