    [TestFixture]
    public class LoginTests : BaseTest
    {
        private const string BaseUrl = "https://www.saucedemo.com/";
        private const string ValidUsername = "standard_user";
        private const string ValidPassword = "secret_sauce";

        [Test]
        public void Login_WithValidCredentials_ShouldNavigateToInventory()
        {
            var login = new LoginPage(Driver);
            login.Navigate();
            Assert.IsTrue(login.IsAtLoginPage(), "Not at login page after navigate");

            login.LoginAs(ValidUsername, ValidPassword);

            var inventory = new InventoryPage(Driver);
            Assert.IsTrue(inventory.IsLoaded(), "Inventory page was not loaded after login with valid credentials");
        }

        [Test]
        public void AddProductToCart_WithValidCredentials_ShouldIncreaseCartBadge()
        {
            var login = new LoginPage(Driver);
            login.Navigate();
            login.LoginAs(ValidUsername, ValidPassword);

            var inventory = new InventoryPage(Driver);
            Assert.IsTrue(inventory.IsLoaded(), "Inventory page not loaded");

            // Ensure cart is initially empty
            var initialCount = inventory.GetCartBadgeCount();

            inventory.AddFirstProductToCart();

            var afterCount = inventory.GetCartBadgeCount();

            Assert.Greater(afterCount, initialCount, "Cart badge did not increase after adding a product");
        }

